def command(src):
 b=base64.b64encode(zlib.compress((PREFIX+src).encode(),9)).decode();code='import base64,zlib;exec(compile(zlib.decompress(base64.b64decode('+repr(b)+')),"<lqi-freeze>","exec"))'
 c=shlex.join(['/opt/conda/envs/adapointr-mamba/bin/python3.10','-I','-S','-B','-c',code]);assert len(c.encode())<=2048;return c
